// lib
using MessagePack;
namespace Lib;

[MessagePackObject]
public class Base
{
    [Key("a")] public int BaseValue { get; set; }
}
// app
using MessagePack;
namespace App;

// Derived's own members are enumerated first, so "a" is already in stringMembers when the
// inherited Lib.Base.BaseValue (metadata, no DeclaringSyntaxReferences) is reached with the same string key.
// Old: reports MsgPack005 with a null location, then stringMembers.Add throws ArgumentException.
// New: reports MsgPack005 only.
[MessagePackObject]
public class Derived : Lib.Base
{
    [Key("a")] public int DerivedValue { get; set; }
}

public static class Program
{
    public static void Main()
    {
        var d = new Derived { DerivedValue = 1, BaseValue = 2 };
        System.Console.WriteLine(d.DerivedValue + d.BaseValue);
    }
}

